from typing import List
from collections import Counter

def count_balanced_substrings(s: str) -> int:
    bal, seen, total = 0, Counter({0: 1}), 0
    for ch in s:
        if ch == "F":
            bal += 1
        elif ch == "N":
            bal -= 1
        total += seen[bal]
        seen[bal] += 1
    return total
